const params=new URLSearchParams(location.search);const state=params.get('state')||'default';const root=document.querySelector('[data-realization-root]');if(root)root.dataset.activeState=state;document.querySelectorAll('[data-set-state]').forEach(button=>{button.classList.toggle('active',button.dataset.setState===state);button.addEventListener('click',()=>{const next=new URL(location.href);next.searchParams.set('state',button.dataset.setState);location.href=next})});document.querySelectorAll('[data-toggle-trace]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.traceable').forEach(node=>node.dataset.traceVisible=node.dataset.traceVisible!=='true')}));